-- Root-scope regression coverage for the system views added in batch 04.
-- Master files are generated by the integration environment.

USE defaultdb;
DROP DATABASE IF EXISTS is_views_04 CASCADE;
CREATE DATABASE is_views_04;
SET DATABASE = is_views_04;
CREATE SCHEMA is_views_04_schema;

-- user_attributes: root can inspect its account, while KWDB has no source for
-- MySQL host-qualified identities or JSON account attributes.
SELECT "USER",
       host IS NULL AS host_is_null,
       "ATTRIBUTE" IS NULL AS attribute_is_null
FROM information_schema.user_attributes
WHERE "USER" = 'root';

-- partitions: cover the supported LIST, RANGE, and HASH representations.
CREATE TABLE is_views_04_schema.list_partition_table (
    region INT,
    id INT,
    PRIMARY KEY (region, id)
) PARTITION BY LIST (region) (
    PARTITION p_east VALUES IN (1),
    PARTITION p_west VALUES IN (2)
);

CREATE TABLE is_views_04_schema.range_partition_table (
    id INT PRIMARY KEY
) PARTITION BY RANGE (id) (
    PARTITION p_low VALUES FROM (1) TO (10),
    PARTITION p_high VALUES FROM (10) TO (20)
);

CREATE TABLE is_views_04_schema.hash_partition_table (
    bucket INT PRIMARY KEY
) PARTITION BY HASH (bucket) (
    PARTITION p_hash_0 VALUES IN (0),
    PARTITION p_hash_1 VALUES IN (1)
);

-- Exercise the public SHOW path that delegates through the legacy partition
-- columns. Its zone configuration text is captured by the generated masters.
SHOW PARTITIONS FROM TABLE is_views_04_schema.list_partition_table;

SELECT table_catalog, table_schema, table_name,
       partition_name, subpartition_name,
       partition_ordinal_position, subpartition_ordinal_position,
       partition_method, subpartition_method,
       partition_expression, subpartition_expression,
       partition_description
FROM kwdb_internal.partitions
WHERE table_catalog = 'is_views_04'
  AND table_schema = 'is_views_04_schema'
  AND table_name IN (
      'list_partition_table',
      'range_partition_table',
      'hash_partition_table'
  )
ORDER BY table_name, partition_ordinal_position;

SELECT table_name,
       partition_description =
           coalesce(list_value, range_value, hash_value)
           AS description_matches_legacy_value,
       table_rows IS NULL
           AND avg_row_length IS NULL
           AND data_length IS NULL
           AND max_data_length IS NULL
           AND index_length IS NULL
           AND data_free IS NULL
           AS size_fields_are_null,
       create_time IS NULL
           AND update_time IS NULL
           AND check_time IS NULL
           AND checksum IS NULL
           AND partition_comment IS NULL
           AND nodegroup IS NULL
           AND tablespace_name IS NULL
           AS unsupported_fields_are_null
FROM kwdb_internal.partitions
WHERE table_catalog = 'is_views_04'
  AND table_schema = 'is_views_04_schema'
ORDER BY table_name, partition_ordinal_position;

-- column_statistics: single-column statistics produce one JSON histogram row.
-- Ordinary relational multi-column statistics are not supported in this branch.
CREATE TABLE is_views_04_schema.statistics_table (
    id INT PRIMARY KEY,
    value INT,
    category STRING
);

INSERT INTO is_views_04_schema.statistics_table
VALUES
    (1, 10, 'a'),
    (2, 10, 'a'),
    (3, 20, 'b'),
    (4, 30, 'c'),
    (5, NULL, 'c');

CREATE STATISTICS is_views_04_value_stats
ON value
FROM is_views_04_schema.statistics_table;

SELECT schema_name, table_name, column_name,
       histogram->>'histogram-type' AS histogram_type,
       (histogram->>'number-of-buckets-specified')::INT AS bucket_count,
       (histogram->>'null-values')::DECIMAL = 0.2 AS null_fraction_matches,
       histogram->>'data-type' AS data_type
FROM information_schema.column_statistics
WHERE schema_name = 'is_views_04_schema'
  AND table_name = 'statistics_table'
ORDER BY column_name;

-- processlist is dynamic, so assert only stable properties of the root query
-- that reads the view instead of materializing IDs, elapsed time, or SQL text.
SELECT count(*) > 0 AS has_current_root_query
FROM information_schema.processlist
WHERE "USER" = 'root'
  AND length(id) = 32
  AND command = 'Query'
  AND "time" >= 0
  AND state IN ('PREPARING', 'EXECUTING')
  AND info LIKE '%information_schema.processlist%';

USE defaultdb;
DROP DATABASE is_views_04 CASCADE;
